SELECT s.name
FROM sets s
WHERE EXISTS (
    SELECT 1 FROM set_translations st
    WHERE st.setCode = s.code AND st.language = 'Korean'
)
AND NOT EXISTS (
    SELECT 1 FROM set_translations st
    WHERE st.setCode = s.code AND st.language LIKE '%Japanese%'
);

SELECT ROUND(100.0 * SUM(CASE WHEN Diagnosis = 'BEHCET' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percentage
FROM Patient
WHERE SEX = 'M' AND strftime('%Y', "First Date") = '1981';
